class Solution {
public:
    vector<long long> maximumEvenSplit(long long finalSum) {
        if (finalSum % 2) return {};
        vector<long long> res;
        long long cur = 2;
        while (finalSum >= cur) {
            res.push_back(cur);
            finalSum -= cur;
            cur += 2;
        }
        if (finalSum > 0) res.back() += finalSum;
        return res;
    }
};

