class Solution {
    public List<Long> maximumEvenSplit(long finalSum) {
        List<Long> res = new ArrayList<>();
        if (finalSum % 2 != 0) return res;
        long cur = 2;
        while (finalSum >= cur) {
            res.add(cur);
            finalSum -= cur;
            cur += 2;
        }
        if (finalSum > 0) {
            res.set(res.size() - 1, res.get(res.size() - 1) + finalSum);
        }
        return res;
    }
}

