class Solution:
    def maximumEvenSplit(self, finalSum: int) -> List[int]:
        if finalSum % 2:
            return []
        k = (math.isqrt(4 * finalSum + 1) - 1) // 2
        res = [2 * i for i in range(1, k + 1)]
        res[-1] += finalSum - k * (k + 1)
        return res

