public:
    vector<long long> maximumEvenSplit(long long finalSum) {
        if (finalSum % 2) return {};
        long long k = (long long)((sqrt((double)(4 * finalSum + 1)) - 1) / 2);
        while (k * (k + 1) > finalSum) k--;
        while ((k + 1) * (k + 2) <= finalSum) k++;
        vector<long long> res;
        for (long long i = 1; i <= k; i++) res.push_back(2 * i);
        res.back() += finalSum - k * (k + 1);
        return res;
    }
};

